1261		private async computeHooks(token: CancellationToken): Promise<IConfiguredHooksInfo | undefined> {
1262			const useChatHooks = this.configurationService.getValue(PromptsConfig.USE_CHAT_HOOKS);
1263			if (!useChatHooks) {
1264				return undefined;
1265			}
1266	
1267			if (!this.workspaceTrustService.isWorkspaceTrusted()) {
1268				return undefined;
1269			}
1270	
1271			const useClaudeHooks = this.configurationService.getValue<boolean>(PromptsConfig.USE_CLAUDE_HOOKS);
1272			const hookFiles = await this.listPromptFiles(PromptsType.hook, token);
1273	
1274			this.logger.trace(`[PromptsService] Found ${hookFiles.length} hook file(s).`);
1275	
1276			// Get user home for tilde expansion
1277			const userHomeUri = await this.pathService.userHome();
1278			const userHome = userHomeUri.scheme === Schemas.file ? userHomeUri.fsPath : userHomeUri.path;
1279	
1280			let hasDisabledClaudeHooks = false;
1281			const collectedHooks = new Map<HookType, IHookCommand[]>();
1282	
1283			const defaultFolder = this.workspaceService.getWorkspace().folders[0];
1284	
1285			for (const hookFile of hookFiles) {
1286				try {
1287					const content = await this.fileService.readFile(hookFile.uri);
1288					const json = parseJSONC(content.value.toString());
1289	
1290					// Resolve the workspace folder that contains this hook file for cwd resolution,
1291					// falling back to the first workspace folder for user-level hooks outside the workspace
1292					const hookWorkspaceFolder = this.workspaceService.getWorkspaceFolder(hookFile.uri) ?? defaultFolder;
1293					const workspaceRootUri = hookWorkspaceFolder?.uri;
1294	
1295					// Use format-aware parsing that handles Copilot and Claude formats
1296					const { format, hooks, disabledAllHooks } = parseHooksFromFile(hookFile.uri, json, workspaceRootUri, userHome);
1297	
1298					// Skip files that have all hooks disabled
1299					if (disabledAllHooks) {
1300						this.logger.trace(`[PromptsService] Skipping hook file with disableAllHooks: ${hookFile.uri}`);
1301						continue;
1302					}
1303	
1304					if (format === HookSourceFormat.Claude && useClaudeHooks === false) {
1305						const hasAnyCommands = [...hooks.values()].some(({ hooks: cmds }) => cmds.length > 0);
1306						if (hasAnyCommands) {
1307							hasDisabledClaudeHooks = true;
1308						}
1309	
1310						this.logger.trace(`[PromptsService] Skipping Claude hook file (disabled via setting): ${hookFile.uri}`);
1311						continue;
1312					}
1313	
1314					for (const [hookType, { hooks: commands }] of hooks) {
1315						for (const command of commands) {
1316							let bucket = collectedHooks.get(hookType);
1317							if (!bucket) {
1318								bucket = [];
1319								collectedHooks.set(hookType, bucket);
1320							}
1321							bucket.push(command);
1322							this.logger.trace(`[PromptsService] Collected ${hookType} hook from ${hookFile.uri} (format: ${format})`);
1323						}
1324					}
1325				} catch (error) {
1326					this.logger.warn(`[PromptsService] Failed to parse hook file: ${hookFile.uri}`, error);
1327				}
1328			}
1329	
1330			// Collect hooks from agent plugins
1331			const plugins = this.agentPluginService.plugins.get();
1332			for (const plugin of plugins) {
1333				if (!isContributionEnabled(plugin.enablement.get())) {
1334					continue;
1335				}
1336				for (const hook of plugin.hooks.get()) {
1337					let bucket = collectedHooks.get(hook.type);
1338					if (!bucket) {
1339						bucket = [];
1340						collectedHooks.set(hook.type, bucket);
1341					}
1342					bucket.push(...hook.hooks);
1343				}
1344			}
1345	
1346			// Check if any hooks were collected
1347			if (collectedHooks.size === 0) {
1348				this.logger.trace('[PromptsService] No valid hooks collected.');
1349				return undefined;
1350			}
1351	
1352			// Build the result
1353			const result: ChatRequestHooks = Object.fromEntries(collectedHooks) as ChatRequestHooks;
1354	
1355			this.logger.trace(`[PromptsService] Collected hooks: ${JSON.stringify(Object.keys(result))}`);
1356			return { hooks: result, hasDisabledClaudeHooks };
1357		}
