17	/**
18	 * Manages built-in internal customizations (skills, instructions, agents, etc.)
19	 * backed by a readonly virtual filesystem.
20	 *
21	 * To add a new internal skill, create an {@link InternalSkill} instance and
22	 * register it in the constructor.
23	 */
24	export class ChatInternalCustomizations extends Disposable {
25	
26		private readonly skills: readonly InternalSkill[];
27		private readonly skillsByUri = new Map<string, InternalSkill>();
28	
29		constructor(fileService: IFileService) {
30			super();
31	
32			const { provider, disposable: fsDisposable } = registerChatInternalFileSystem(fileService);
33			this._register(fsDisposable);
34	
35			// --- Built-in skills (add new entries here) ---
36			this.skills = [
37				troubleshootSkill,
38			];
39	
40			for (const skill of this.skills) {
41				provider.registerFile(skill.uri, skill.content);
42				this.skillsByUri.set(skill.uri.toString(), skill);
43				this._register(skill);
44			}
45	
46		}
47	
48		/**
49		 * Returns the {@link IAgentSkill} metadata for all internal skills,
50		 * for injection into the skills list.
51		 */
52		getSkills(): readonly IAgentSkill[] {
53			return this.skills.map(s => s.skill);
54		}
55	
56		/**
57		 * Looks up the {@link InternalSkill} instance for a given URI,
58		 * e.g. to check its {@link InternalSkill.when} clause.
59		 */
60		getInternalSkillByUri(uri: URI): InternalSkill | undefined {
61			return this.skillsByUri.get(uri.toString());
62		}
63	
64		/**
65		 * Returns internal prompt file paths for a given customization type.
66		 */
67		getPromptPaths(type: PromptsType): readonly IInternalPromptPath[] {
68			if (type === PromptsType.skill) {
69				return this.skills.map(s => ({
70					uri: s.uri,
71					storage: PromptsStorage.internal as const,
72					type,
73					name: s.name,
74					description: s.description,
75				}));
76			}
77			return [];
78		}
79	}
